pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: from address, value v, and length of tos (as uint256) which we bound to a small positive length
    function testFuzz_property(address from, uint256 v, uint256 tosLen) public {
        // keep tosLen wide but ensure it's non-zero to be in admissible domain (require in C)
        tosLen = bound(tosLen, 1, 5); // small upper bound to keep test cheap but still fuzzy

        // prepare an array of recipient addresses: use helper Callee which always accepts the call
        address[] memory tos = new address[](tosLen);
        Callee callee = new Callee();
        for (uint i = 0; i < tosLen; i++) {
            tos[i] = address(callee);
        }

        // Call transfer and capture whether it returns true (non-reverting, read return value via try/catch)
        bool ok;
        try c.transfer(from, address(callee), tos, v) returns (bool ret) {
            ok = ret;
        } catch {
            ok = false; // should not revert for this callee; treat revert as violation of admissible domain
        }

        // General rule: for any admissible input (non-empty tos and a callee that does not revert), reference C returns true.
        // The mutant returns false for some such inputs; assertTrue here should pass on reference and fail on mutant for some fuzz case.
        assertTrue(ok);
    }
}

// Minimal adversarial/helper callee that always accepts the low-level call and returns true for selector used.
contract Callee {
    // implement transferFrom(address,address,uint256) to simply return true
    function transferFrom(address, address, uint256) public pure returns (bool) {
        return true;
    }

    // fallback to accept any call and return success
    fallback() external payable {
        // do nothing, succeed
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    // A minimal helper callee that emulates a successful transferFrom: it simply provides
    // a function matching the selector transferFrom(address,address,uint256) and returns true implicitly.
    // This ensures the low-level call in C succeeds for non-empty _tos.
    contract SuccessfulCallee {
        // matches transferFrom(address,address,uint256)
        function transferFrom(address, address, uint256) external pure returns (bool) {
            return true;
        }
    }

    function setUp() public { c = new C(); }

    // fuzzed params: from actor, callee address (we'll deploy a helper and use its address),
    // number of tos and a value. We must include at least one fuzz param; include multiple so fuzzer can find distinguishing input.
    function testFuzz_property(address from, uint8 tosCount, uint256 v) public {
        // keep tosCount reasonable but allow zero (the contract requires >0 so we must exclude zero)
        // bound tosCount to [0, 5] to let fuzzer pick small arrays; we will assume >0 below
        tosCount = uint8(bound(tosCount, 0, 5));
        vm.assume(tosCount > 0);

        // deploy a helper that will succeed on calls
        SuccessfulCallee helper = new SuccessfulCallee();
        address caddress = address(helper);

        // build a dynamic _tos array of length tosCount with arbitrary addresses derived from `from` and v
        address[] memory _tos = new address[](tosCount);
        for (uint i = 0; i < tosCount; i++) {
            // create varied addresses using hash so fuzzer influences them via `from` and loop index
            _tos[i] = address(uint160(uint256(keccak256(abi.encodePacked(from, v, i)))));
        }

        // Call transfer and capture whether it completed (did not revert) and the returned value.
        bool ok;
        bool ret;
        try c.transfer(from, caddress, _tos, v) returns (bool r) {
            ok = true;
            ret = r;
        } catch {
            ok = false;
            ret = false; // irrelevant when reverted
        }

        // The universal property: whenever the call completes (ok == true), the reference implementation
        // must return true. The mutant that returns `!true` would return false while still completing,
        // so the single assertion below holds for the reference for all inputs and is violated by the mutant
        // for some inputs the fuzzer will find (any input that completes).
        assertTrue(!ok || ret);
    }
}

// Minimal helper defined after InvMutTest (as required).
contract SuccessfulCallee {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed params: from (address), calleeIsGood (bool) to decide which helper to use, and uint v and uint tosLen
    function testFuzz_property(address from, bool calleeIsGood, uint256 v, uint256 tosLen) public {
        // keep tosLen in a small but non-empty range to satisfy require(_tos.length > 0)
        tosLen = bound(tosLen, 1, 8);

        // prepare an array of addresses to pass as _tos; deploy adversarial helper and use its address for each entry
        address[] memory tos = new address[](tosLen);

        // deploy the appropriate helper: GoodCallee forwards the call and returns true; RevertingCallee reverts
        address helper = address(new GoodCallee());
        if (!calleeIsGood) {
            helper = address(new GoodCallee()); // still use GoodCallee: we want a completing call so mutant and ref both complete
        }

        // fill tos with the helper's address (we want the low-level call to succeed so the reference returns true)
        for (uint i = 0; i < tosLen; i++) {
            tos[i] = helper;
        }

        // ensure 'from' is some nonzero address (keep wide but avoid address(0) which might be considered edge-case)
        if (from == address(0)) from = address(0x1);

        // Call transfer and observe its returned boolean via try/catch to convert reverts to false.
        bool ok;
        try c.transfer(from, helper, tos, v) returns (bool ret) {
            ok = ret;
        } catch {
            ok = false;
        }

        // General property: for any admissible input where the call completes, the correct contract returns true.
        // Here we assert that the call returned true (this will hold for the reference C for all such inputs,
        // and will fail for the mutant which returns false when the call completes).
        assertTrue(ok);
    }
}

// Helper that accepts the low-level call and returns true (mimics a successful callee for transferFrom)
contract GoodCallee {
    // matches selector transferFrom(address,address,uint256)
    function transferFrom(address, address, uint) external returns (bool) {
        return true;
    }
}
